            { q: "Qaysi ko'rsatkichni birinchi tekshirasiz?", o: ["Oylik buyurtmalar soni va tushum", "Xodimlar soni", "Ofis ijarasi"], a: 0, why: "\"Savdo yomon\" — bu buyurtmalar va tushum haqida." },
            { q: "Buyurtmalar faqat Sergelida tushgan. Keyingi qadam?", o: ["Sergelida nima o'zgarganini tekshirish: yetkazish, narx, raqobatchi", "Butun shaharda reklamani to'xtatish", "Hech narsa qilmaslik"], a: 0, why: "Muammo bitta hududda — sababni o'sha yerdan izlaymiz." }
